'use strict';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog'),E=KK,KEY='kode-kecil-v3';
let storageOK=true,progress={done:[],last:0},level=0,filter=null,m=null,state=null,epoch=0,sound=false,audioCtx=null;
const clone=v=>structuredClone(v),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cleanProgress(p){if(!p||!Array.isArray(p.done)||p.done.length>TOTAL_MISSIONS||!p.done.every(n=>Number.isInteger(n)&&n>=0&&n<TOTAL_MISSIONS))throw Error('Format progres tidak sesuai');return{done:[...new Set(p.done)],last:Number.isInteger(p.last)&&p.last>=0&&p.last<TOTAL_MISSIONS?p.last:0};}
try{const raw=localStorage.getItem(KEY);if(raw)progress=cleanProgress(JSON.parse(raw));}catch{storageOK=false;}
level=E.make(progress.last).level;
function save(){syncShell();try{localStorage.setItem(KEY,JSON.stringify(progress));storageOK=true;}catch{storageOK=false;}}
function speak(text,force=false){if(sound||force)BimoVoice.say(text);}
function stop(){GameSFX.stop();cancelDrag();GameMotion.clear();epoch++;if(state)state.busy=false;BimoVoice.stop();}
function setStatus(text,kind='',narrate=true){const coach=$('#coach');if(coach)coach.innerHTML='';document.querySelectorAll('.clue-focus').forEach(el=>el.classList.remove('clue-focus'));const buddy=$('#bimoBuddy');if(buddy)buddy.dataset.mood=kind==='thinking'?'think':kind==='good'?'happy':'idle';const s=$('#status');if(s){s.textContent=text;s.className='status '+kind;}if(narrate)speak(text);}
function next(){return nextInPath(E.make(progress.last).type);}
function theme(){return E.themes[m.theme];}function typeInfo(){return E.types.find(t=>t.id===m.type);}
function card(c,{small=false,neutral=false}={}){const o=theme().objects[c.o],co=E.colors[c.c];return `<span class="picture-card ${small?'small':''} ${c.big?'big-picture':''}" role="img" aria-label="${escapeHTML(cardName(c))}" style="--card-color:${neutral?'#eef1e5':co.hex}"><span class="object">${o.icon}</span><span class="color-mark" aria-hidden="true">${co.mark}</span>${c.badge?'<span class="badge-star">★</span>':''}</span>`;}
function cardName(c){return `${theme().objects[c.o].name}, ${E.colors[c.c].name}${m.type==='detective'||m.type==='factory'?', '+(c.big?'besar':'kecil')+(c.badge?', berbintang':', tanpa bintang'):''}`;}
function home(){gameMenu();}
function chapter(){journey(filter||m?.type||'route');}
function initState(){const s={busy:false,selection:null,program:[],fn:[],active:-1};switch(m.type){case'cause':s.answer=m.questions.map(()=>-1);break;case'sequence':case'debug':s.answer=[...m.tiles];break;case'memory':s.matched=m.cards.map(()=>false);s.flipped=[];s.tries=0;break;case'sort':s.answer=m.cards.map(()=>-1);break;case'pattern':s.answer=m.blanks.map(()=>null);s.selection=0;break;case'mosaic':s.answer=[...m.tiles];break;case'matrix':s.answer=[...m.clues];s.selection=m.clues.indexOf(-1);break;case'factory':s.outputs=clone(m.inputs);break;case'route':s.pos=[...m.start];s.stars=[];break;case'music':s.playing=-1;s.heard=[];break;case'detective':s.answer=null;break;case'packing':s.answer=m.cards.map(()=>-1);break;}return s;}
function sortHouse(i){
  const {a,b}=m.rule;
  const color=m.mode===0?E.colors[(a+i)%4]:m.mode===2?E.colors[(b+Math.floor(i/2))%4]:null;
  const object=m.mode===1?theme().objects[(a+i)%4]:m.mode===2?theme().objects[(a+i%2)%4]:null;
  const sign=object?object.icon:color?color.mark:i===0?'✓':'✕';
  return `<span class="sort-house" aria-hidden="true"><svg viewBox="0 0 160 140" focusable="false"><path d="M25 60H135V125Q135 132 128 132H32Q25 132 25 125Z" fill="${color?color.hex:'#e5e8df'}" stroke="#45584b" stroke-width="3"/><path d="M12 64L80 10L148 64Z" fill="${color?color.hex:'#c9d4c3'}" stroke="#45584b" stroke-width="3" stroke-linejoin="round"/><rect x="48" y="68" width="64" height="54" rx="16" fill="#fffdf5" stroke="#45584b" stroke-width="2"/><text x="80" y="105" text-anchor="middle" font-size="${object?36:32}" fill="#34493e">${sign}</text></svg></span>`;
}
function sortRuleVisual(){
  const {a,b}=m.rule;
  const swatch=c=>`<span class="rule-swatch" style="background:${E.colors[c].hex}">${E.colors[c].mark}</span>`;
  return `<span class="sort-rule-visual" aria-hidden="true">${m.mode===3?`<span>${theme().objects[a].icon}</span><small>+</small>${swatch(b)}`:`${swatch(b)}<small>atau</small>${swatch((b+1)%4)}<small>+</small><span class="rule-not">${theme().objects[a].icon}<b>✕</b></span>`}</span>`;
}
function missionBrief(){if(m.type==='cause')return m.questions[state.question||0].text;if(m.type==='matrix')return 'Isi kotak kosong. Ke samping dan ke bawah, jangan ada gambar kembar. Kotak 🔒 tidak bisa diubah.';if(m.type==='route')return 'Susun panah agar Bimo sampai ke baterai 🔋.'+(m.stars.length?' Di petak ⭐, pakai kartu ambil bintang.':'');if(m.type==='sort'&&!m.ruleText)return 'Lihat warna dan gambar di rumah. Seret kartu ke rumah yang sama.';if(m.type==='mosaic')return 'Seret potongan ke potongan lain. Keduanya akan bertukar tempat. Buat gambar seperti contoh!';if(m.type==='factory')return factoryInstruction()+' Pilih sihir, lalu tekan Bim Salabim. '+(m.require.includes('repeat')?'Pakai kotak Ulang. ':'')+(m.require.includes('if')?'Pakai mesin Jika merah.':'');if(m.type==='music')return m.brief+' '+(m.require.includes('function')?'Buat dan panggil Jurus Irama.':m.require.includes('repeat')?'Gunakan kotak Ulang.':'');if(m.type==='sort'&&m.ruleText)return 'Masukkan ke rumah Cocok hanya jika: '+m.ruleText+'.';if(m.type==='packing'&&m.counts)return m.brief+' Tiap tas harus berisi 3 bekal.';return m.brief;}
function openMission(id){stop();m=E.make(id);filter=m.type;level=m.level;progress.last=id;save();state=initState();const t=typeInfo(),w=theme();applyWorldTheme(w.slug);app.innerHTML=`<div class="simple-game-header"><button class="game-back" data-action="journey" data-value="${m.type}" aria-label="Kembali ke level ${t.name}">←</button><span class="game-header-icon" aria-hidden="true">${t.icon}</span><h1>${t.name}</h1><span class="pill">Level ${pathIds(m.type).indexOf(id)+1}</span><button class="listen" data-action="listen" aria-label="Bacakan petunjuk">🔊</button></div>${['cause','route','factory'].includes(m.type)?'':`<div class="instruction"><p id="instruction">${escapeHTML(shortInstruction())}</p></div>`}<div id="game" class="game game-${m.type}"></div><div class="status" id="status" role="status" aria-live="polite">${initialMessage()}</div><div id="coach"></div><div class="game-actions"><button class="primary" data-action="check" id="check">${['factory','route','music'].includes(m.type)?'▶ Jalankan rencanaku':'✓ Cek'}</button><button class="secondary" data-action="hint">💡 Bantuan</button>${['route','factory'].includes(m.type)?'':'<button class="secondary" data-action="reset">↶ Ulang</button>'}</div><details class="compact-help"><summary>👀 Cara main</summary>${childGuide()}</details><details class="guide"><summary>☀️ Panduan pendamping · misi ${id+1}</summary><div><p><b>Tujuan:</b> ${t.goal}</p><p><b>Tantangan misi ini:</b> ${escapeHTML(E.describe(m))}</p><p><b>Pemanasan tanpa layar (±5 menit):</b> ${t.off}</p><p><b>Bermain (±10 menit):</b> ${escapeHTML(missionBrief())} Minta anak menebak, mencoba, lalu menjelaskan. Biarkan salah menjadi bahan diskusi.</p><p><b>Cerita kembali (±5 menit):</b> ${t.reflect}</p><p><b>Tantangan kreatif:</b> anak membuat versi sendiri memakai kertas atau benda di rumah, lalu mengajari Anda. Naik tingkat ketika anak dapat menjelaskan caranya; boleh kembali ke tingkat sebelumnya.</p><p>Durasi fleksibel. Satu misi bukan kewajiban satu sesi penuh. Berhenti ketika anak lelah atau mulai tidak menikmati.</p></div></details>`;renderGame();window.scrollTo(0,0);}
function initialMessage(){if(!['memory','mosaic','matrix'].includes(m.type))return playGuides[m.type][0]+' Aku Bimo. Yuk, coba bersama! 🤖';return m.type==='memory'?'Ketuk dua kartu. Ingat gambar DAN warna bingkainya.':m.type==='mosaic'?'Cari sudut dan tepi gambar dulu. Seret satu potongan ke potongan lain untuk menukar.':m.type==='matrix'?'Kotak bergembok adalah petunjuk. Pilih kotak kosong, lalu pilih gambar.':'Lihat dulu, buat rencana, lalu coba. Tidak perlu buru-buru. 🌱';}
function btn(action,value,html,cls='',label=''){return `<button class="${cls}" data-action="${action}" data-value="${value}"${label?` aria-label="${escapeHTML(label)}"`:''}${state.busy?' disabled':''}>${html}</button>`;}
function renderGame(){const g=$('#game');if(!g||!m)return;const beforeMotion=GameMotion.capture(g,m.id);switch(m.type){
case'cause':case'sequence':case'debug':g.innerHTML=renderLesson();break;
case'memory':g.innerHTML=`<div class="game-meta"><span>🐾 ${state.matched.filter(Boolean).length/2} / ${m.pairs} pasangan</span><span>Gambar sama + warna sama</span></div><div class="memory-board" style="--cols:${m.pairs<=4?4:m.pairs<=6?4:4}">${m.cards.map((c,i)=>{const revealed=state.matched[i]||state.flipped.includes(i);return btn('memory',i,revealed?card(c):'<span class="card-back">?</span>',`memory-tile ${state.matched[i]?'matched':''} ${revealed?'revealed':''}`,revealed?`${cardName(c)}${state.matched[i]?', pasangan ditemukan':''}`:`Buka kartu ${i+1}`);}).join('')}</div><p class="mini-help">Tanda ● ■ ▲ ◆ ikut membedakan warna.</p>`;break;
case'sort':g.innerHTML=sortBoard();break;
case'pattern':g.innerHTML=`<div class="game-meta"><span>🚂 Polanya</span><span>?</span></div><div class="pattern-train">${m.sequence.map((c,k)=>{const i=m.blanks.indexOf(k);return i<0?`<div class="train-car">${card(c,{small:true})}<small>${k+1}</small></div>`:btn('select',i,`${state.answer[i]?card(state.answer[i],{small:true}):'<span class="blank-icon">?</span>'}<small>${k+1}</small>`,`train-car missing ${state.selection===i?'selected':''}`,`Gerbong kosong ${k+1}`);}).join('')}</div><p class="mini-help">Seret gambar ke gerbong bertanda ?. Bisa juga ketuk gerbong, lalu gambarnya.</p><div class="choice-row">${m.choices.map((c,i)=>btn('pattern',i,card(c),`choice`,cardName(c))).join('')}</div>`;break;
case'mosaic':{const uri=pictureURI();g.innerHTML=`<div class="puzzle-layout"><div><div class="game-meta"><span>🧩 ${m.n} × ${m.n} potongan</span><span>Seret untuk bertukar tempat</span></div><div class="mosaic-board" style="--n:${m.n}">${state.answer.map((v,i)=>btn('tile',i,`<span style="background-image:url('${uri}');background-size:${m.n*100}% ${m.n*100}%;background-position:${(v%m.n)/(m.n-1)*100}% ${Math.floor(v/m.n)/(m.n-1)*100}%"></span>`,`puzzle-tile ${state.selection===i?'selected':''}`,`Potongan di baris ${Math.floor(i/m.n)+1}, kolom ${i%m.n+1}`)).join('')}</div></div><div class="puzzle-example"><b>🎯 Contoh</b><img src="${uri}" alt="Gambar utuh untuk dicontoh: ${theme().objects[m.animal].name}"></div></div>`;break;}
case'matrix':g.innerHTML=`<div class="matrix-layout"><div class="matrix-board" style="--n:${m.n}">${state.answer.map((v,i)=>{const fixed=m.clues[i]>=0;return `<button class="matrix-cell ${fixed?'fixed':''} ${state.selection===i?'selected':''}" data-action="${fixed?'fixed':'select'}" data-value="${i}" aria-label="Baris ${Math.floor(i/m.n)+1}, kolom ${i%m.n+1}: ${v<0?'kosong':theme().objects[v].name}${fixed?', petunjuk tetap':''}">${v<0?'?':theme().objects[v].icon}${fixed?'<small>🔒</small>':''}</button>`;}).join('')}</div><div><div class="visual-rule-banner"><span>↔</span><span>↕</span><b>Jangan kembar</b></div><div class="choice-row">${E.range(m.n).map(i=>btn('matrix',i,theme().objects[i].icon,'symbol-button',theme().objects[i].name)).join('')}</div>${btn('matrix',-1,'⌫ Hapus','secondary')}</div></div>`;break;
case'factory':g.innerHTML=factoryBoard();break;
case'route':g.innerHTML=`<div class="route-layout"><div class="route-map"><h2 class="route-mission">Bantu Bimo mencapai baterai!</h2><div class="route-board" style="--n:${m.n}">${E.range(m.n*m.n).map(i=>{const p=[i%m.n,Math.floor(i/m.n)],k=p.join(','),here=p.join(',')===state.pos.join(','),wall=m.walls.includes(k),star=m.stars.some(s=>s.join(',')===k)&&!state.stars.includes(k);return `<div class="route-cell ${wall?'wall':''} ${here?'here':''}" aria-label="Baris ${p[1]+1}, kolom ${p[0]+1}: ${here?'Bimo':wall?'rintangan':star?'bintang':k===m.goal.join(',')?'baterai':'jalan'}">${here?'<span class="route-avatar" aria-hidden="true">🤖</span>':wall?'🪨':star?'⭐':k===m.goal.join(',')?'🔋':''}</div>`;}).join('')}</div><p class="route-legend">🪨 Hindari batu${m.stars.length?' · ⭐ '+state.stars.length+'/'+m.stars.length:''}</p></div>${routeEditor()}</div>`;break;
case'music':g.innerHTML=`<div class="music-score"><div class="game-meta"><b>🎼 Irama tujuan</b>${btn('listenMusic','', '▶ Dengarkan','secondary')}</div><div class="notes">${m.target.map((v,i)=>`<span class="note ${state.playing===i?'playing':''}">${noteIcon(v)}</span>`).join('')}</div><div class="your-notes"><small>🎵 Bunyi buatanmu</small><div class="notes">${state.heard.length?state.heard.map(v=>`<span class="note">${noteIcon(v)}</span>`).join(''):'<span class="empty">▶ Jalankan untuk mendengar</span>'}</div></div></div>${programEditor(['0','1','2','3'])}`;break;
case'detective':g.innerHTML=`<div class="detective-layout"><div class="clue-panel"><h3>🔎 Cari yang cocok</h3><div class="clue-pictures">${m.rules.map(r=>visualClue(r)).join('')}</div>${btn('clues','','🔊 Dengarkan','secondary')}<p class="mini-help">Gambar kecil / besar dan tanda ★ juga bisa menjadi petunjuk.</p></div><div class="suspects">${m.cards.map((c,i)=>btn('suspect',i,card(c),`suspect ${state.answer===i?'selected':''}`,`Pilihan ${i+1}: ${cardName(c)}`)).join('')}</div></div>`;break;
case'packing':g.innerHTML=packingBoard();break;
}preparePlay();decoratePlay();GameMotion.finish(g,beforeMotion,m.id);$('#check').hidden=['cause','memory','route','factory'].includes(m.type);$('#check').disabled=state.busy||m.type==='memory';if(m.type==='memory')$('#check').textContent='🐾 Temukan semua pasangan';}
function sortCard(i,inside=false){return btn('select',i,card(m.cards[i],{small:inside}),`sort-card ${inside?'house-card':'item-card'} ${state.selection===i?'selected':''}`,`${cardName(m.cards[i])}${inside?', di rumah '+(state.answer[i]+1)+'. Pilih atau seret untuk memindahkan.':''}`).replace('<button ',`<button data-card-index="${i}" `);}
function sortBoard(){return `${m.ruleText?`<div class="rule-banner">${sortRuleVisual()}📋 Aturan: <b>${escapeHTML(m.ruleText)}</b></div>`:''}<div class="tray">${m.cards.map((c,i)=>`<div class="sort-slot">${state.answer[i]<0?sortCard(i):btn('returnSort',i,'<span aria-hidden="true">↩</span>','sort-empty-slot',`Slot asal kartu ${i+1}. Kembalikan ${cardName(c)} ke sini.`)}</div>`).join('')}</div><p class="sort-move-help">Seret kartu ke rumah. Mau pindah? Seret lagi ke rumah lain atau tempat semula.</p><div class="bins" style="--bins:${m.bins.length}">${m.bins.map((b,i)=>`<section class="bin sort-home" data-value="${i}" aria-label="Rumah ${i+1}: ${escapeHTML(b)}">${btn('bin',i,`${sortHouse(i)}<b>${escapeHTML(b)}</b><small>${state.answer.filter(v=>v===i).length} kartu</small>`,'sort-house-target',`Masukkan kartu ke rumah ${i+1}: ${b}`)}<div class="placed-items">${m.cards.map((c,j)=>state.answer[j]===i?sortCard(j,true):'').join('')||'<span class="drop-prompt">↓ Taruh di sini</span>'}</div></section>`).join('')}</div>`;}
function factoryInstruction(){return m.allowed.length===1?`Bantu ${theme().objects[m.inputs[0].o].name} berubah menjadi ${E.colors[m.targets[0].c].name}!`:'Ubah gambarmu agar sama dengan tujuan!';}
function factoryBoard(){
 const start=m.inputs[0].c,colors=E.range(4).map(i=>E.colors[(start+i)%4]);
 return `<section class="factory-brief"><span class="factory-buddy" aria-hidden="true">🤖</span><div><h2>${escapeHTML(factoryInstruction())}</h2><p>Pilih sihir. Lalu, Bim Salabim!</p></div>${btn('listen','','🔊','factory-listen','Dengarkan petunjuk sihir')}</section><div class="factory-path"><b>JALAN WARNANYA</b><div class="visual-machine-key"><span>${colors.map((c,i)=>`${i?'<span aria-hidden="true">→</span>':''}<span class="factory-color"><i class="machine-swatch" style="background:${c.hex}" aria-hidden="true">${c.mark}</i><small>${c.name}</small></span>`).join('')}<span title="Kembali ke warna pertama">↻</span></span></div><small>Satu sihir = maju satu warna.</small>${m.allowed.includes('object')?`<div class="factory-object-path">${theme().objects.map(o=>o.icon).join(' → ')} ↻</div>`:''}</div><div class="factory-workshop"><section class="factory-stage ${state.busy?'is-magic':''}">${m.inputs.map((c,i)=>`<div class="factory-pair"><div class="machine-output"><b>${state.busy?'✨ BERUBAH!':'GAMBARMU'}</b>${card(state.outputs[i])}</div><span class="factory-arrow" aria-hidden="true">→</span><div class="factory-target"><b>TUJUAN</b>${card(m.targets[i])}</div></div>`).join('')}</section><div class="factory-console"><section class="factory-spellbox"><h3>✨ KOTAK SIHIR</h3><div class="program" aria-label="Rencana instruksi">${state.program.length?state.program.map((c,i)=>btn('remove',i,`${codeLabel(c)} <small>×</small>`,`token ${c.body?'group':''} ${state.active===i?'playing':''}`,'Hapus kartu '+(i+1)+': '+codeLabel(c))).join(''):'<span class="empty"><span aria-hidden="true">🪄 🪄 🪄</span>Taruh sihirmu di sini!</span>'}</div><div class="palette">${m.allowed.map(t=>btn('add',t,`<b aria-hidden="true">${t==='color'?'🪄':commandIcon(t)}</b><small>${t==='color'?'Ubah Warna!':commandName(t)}</small>`,'command','Tambah '+commandName(t))).join('')}</div>${m.level>=2?`<div class="editor-tools">${btn('repeat',2,'↻ Ulang 2×','secondary')}${btn('repeat',3,'↻ Ulang 3×','secondary')}</div><p class="factory-loop-help">Ulang = jalankan semua sihir lagi.</p>`:''}${m.require.length?`<p class="factory-required">Pakai ${m.require.map(t=>t==='repeat'?'↻ Ulang':'🔴 Jika merah → kuning').join(' dan ')}.</p>`:''}<p class="factory-edit-tip">Ketuk × untuk melepas sihir.</p></section><div class="factory-actions">${btn('reset','','↶<small>Ulangi</small>','factory-reset','Ulang dari awal')}${btn('check','','▶ Bim Salabim!','factory-run')}</div></div></div>`;
}
function packingDots(total,filled=total){return `<span class="packing-dots" aria-hidden="true">${E.range(total).map(i=>`<i class="${i<filled?'filled':''}"></i>`).join('')}</span>`;}
function packingBoard(){return `<div class="bags packing-bags">${m.targets.map((target,b)=>{
 const chosen=m.cards.map((c,i)=>({c,i})).filter(x=>state.answer[x.i]===b),sum=chosen.reduce((n,x)=>n+x.c.value,0),countOK=!m.counts||chosen.length===m.counts[b],balanced=sum===target&&countOK;
 const message=sum>target?`Lebih ${sum-target} titik`:sum<target?(sum?`Kurang ${target-sum} titik`:'Masih kosong'):countOK?'Pas! Hebat!':chosen.length<m.counts[b]?`Butuh ${m.counts[b]-chosen.length} bekal lagi`:`Kelebihan ${chosen.length-m.counts[b]} bekal`;
 return btn('bag',b,`<span class="packing-target">Target: ${target} titik!</span><span class="packing-bag-head"><span class="packing-bag-picture"><span class="bag-icon" aria-hidden="true">🎒</span><b>Tas ${b+1}</b></span><span class="packing-meter"><strong>${sum} <em>/ ${target}</em></strong><span class="packing-status">${balanced?'✓ ':sum>target?'↶ ':''}${message}</span></span></span><span class="packing-progress" aria-label="${sum} dari ${target} titik">${packingDots(target,Math.min(sum,target))}${sum>target?`<small>+${sum-target}</small>`:''}</span>${m.counts?`<span class="packing-count">🎒 ${chosen.length} / ${m.counts[b]} bekal</span>`:''}<span class="placed-items">${chosen.length?chosen.map(({c,i})=>`<span class="packed-card" data-card-index="${i}"><span>${theme().objects[c.o].icon}</span>${packingDots(c.value)}</span>`).join(''):'<span class="packing-drop-hint">↓ Seret bekal ke sini</span>'}</span>`,`bag ${balanced?'balanced':sum>target?'overfull':''}`,`Tas ${b+1}. Target ${target} titik. Terisi ${sum}. ${message}${m.counts?'. '+chosen.length+' dari '+m.counts[b]+' bekal':''}`);
 }).join('')}</div><div class="provisions">${m.cards.map((c,i)=>btn('provision',i,`<span aria-hidden="true">${theme().objects[c.o].icon}</span>${packingDots(c.value)}${state.answer[i]>=0?`<small>↶ Ambil dari tas ${state.answer[i]+1}</small>`:''}`,`provision ${state.selection===i?'selected':''} ${state.answer[i]>=0?'assigned':''}`,`Bekal ${i+1}, ${c.value} titik${state.answer[i]>=0?', ketuk untuk mengeluarkan dari tas '+(state.answer[i]+1):''}`)).join('')}</div><p class="packing-tip">${state.answer.some(v=>v>=0)?'Mau ganti? Ketuk kartu di bawah untuk mengambilnya lagi.':'Seret kartu ke tas. Atau ketuk kartu, lalu tas.'}</p>`;}
function pictureURI(){const w=theme(),c=E.colors[m.color].hex,accent=E.colors[(m.color+2)%4].hex;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400"><rect width="400" height="400" fill="${w.tint}"/><path d="M0 270 Q100 190 210 285 T400 230 V400 H0Z" fill="${c}"/><path d="M0 330 Q150 255 400 310 V400 H0Z" fill="${accent}"/><circle cx="335" cy="62" r="30" fill="#fff5cc"/><path d="M20 25 H100 V105 H20Z" fill="${accent}" opacity=".55"/><path d="M40 45 H80 V85 H40Z" fill="#fff" opacity=".6"/><circle cx="65" cy="190" r="25" fill="${c}"/><path d="M298 190 l35 -55 35 55Z" fill="${accent}"/><path d="M30 365 Q180 330 370 365" fill="none" stroke="#fff9e9" stroke-width="12" stroke-dasharray="16 9"/><text x="200" y="265" text-anchor="middle" font-family="Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif" font-size="165">${w.objects[m.animal].icon}</text><text x="325" y="310" font-family="Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif" font-size="45">${w.objects[(m.animal+1+m.decor)%4].icon}</text><circle cx="70" cy="310" r="12" fill="#fff9e9"/><circle cx="90" cy="290" r="7" fill="#fff9e9"/></svg>`;return 'data:image/svg+xml,'+encodeURIComponent(svg).replaceAll("'",'%27');}
