function ruleText(r){const value=v=>r.field==='o'?theme().objects[v].icon+' '+theme().objects[v].name:r.field==='c'?E.colors[v].mark+' '+E.colors[v].name:r.field==='big'?(v?'besar':'kecil'):(v?'memakai bintang ★':'tanpa bintang');return r.op==='in'?`Pilih ${r.value.map(value).join(' ATAU ')}.`:r.op==='ne'?`BUKAN ${value(r.value)}.`:r.field==='big'?`Gambarnya ${value(r.value)}.`:r.field==='badge'?`${value(r.value)}.`:`${r.field==='c'?'Bingkainya':'Gambarnya'} ${value(r.value)}.`;}
async function memory(i){if(state.busy||state.matched[i]||state.flipped.includes(i))return;GameSFX.play('flip');state.flipped.push(i);renderGame();if(state.flipped.length<2)return;state.tries++;const[a,b]=state.flipped;if(m.cards[a].pair===m.cards[b].pair){state.matched[a]=state.matched[b]=true;state.flipped=[];renderGame();if(E.validate(m,state.matched))win();else{GameSFX.play('star');setStatus('Ketemu kembarnya! Gambar dan warnanya sama. Tos! 🖐️','good');animatePlay('.memory-tile.matched');}}else{state.busy=true;const mismatch=m.cards[a].o===m.cards[b].o?'Gambarnya kembar! Coba lihat warna bingkainya. Sudah sama?':'Gambarnya belum kembar. Ingat satu gambar dulu. Tadi ada di mana, ya?';setStatus(mismatch,'thinking',false);reactBimo('think');renderGame();const token=epoch;await new Promise(r=>setTimeout(r,1100));if(token!==epoch)return;state.flipped=[];state.busy=false;renderGame();GameSFX.play('retry');setStatus(mismatch,'thinking');}}
function hint(){showThinking(false,m.id>=1000?lessonClue():'');}
function wrongMessage(){return diagnoseAttempt().text;}
async function check(){if(state.busy)return;if(m.type==='cause'){const q=state.question||0;if(!m.questions[q].choices[state.answer[q]]?.correct)return showThinking(true,lessonClue());if(E.validate(m,state.answer))return win();state.question=q+1;renderGame();setStatus('Bagus! Coba yang berikutnya.','good');return;}if(['route','factory','music'].includes(m.type))return runProgram();if(m.type==='memory')return;try{if(E.validate(m,state.answer))win();else showThinking(true,m.id>=1000?lessonClue():'');}catch{showThinking(true,'Mari susun dulu jawabannya.');}}
async function runProgram(){if(!state.program.length)return showThinking(true,'Rencananya masih kosong. Tambahkan satu kartu dulu, yuk!');let steps;try{steps=E.flatten(state.program);}catch{return showThinking(true,'Rencananya panjang sekali. Coba kurangi kartunya, lalu jalankan lagi.');}state.busy=true;state.active=-1;const token=epoch;let travel=null;if(m.type==='route'){travel=E.travel(m,state.program);state.pos=[...m.start];state.stars=[];}if(m.type==='factory')state.outputs=clone(m.inputs);if(m.type==='music')state.heard=[];let offsets=[],counter=0;state.program.forEach((c,i)=>{const n=E.flatten([c]).length;for(let j=0;j<n;j++)offsets[counter++]=i;});renderGame();for(let i=0;i<steps.length;i++){if(token!==epoch)return;state.active=offsets[i];if(m.type==='route'){if(i>=travel.history.length-1){state.busy=false;renderGame();return showThinking(true);}state.pos=[...travel.history[i+1].pos];GameSFX.play(travel.history[i+1].stars.length>state.stars.length?'star':'step');state.stars=[...travel.history[i+1].stars];}else if(m.type==='factory'){GameSFX.play('magic');state.outputs=state.outputs.map(c=>E.transform(c,steps[i]));}else{state.playing=i;state.heard.push(steps[i]);playNote(steps[i]);}renderGame();await new Promise(r=>setTimeout(r,500));}if(token!==epoch)return;state.busy=false;state.active=-1;if(m.type==='music')state.playing=-1;renderGame();const req=m.require||[];if(!req.every(t=>E.has(state.program,t)))return showThinking(true,'Untuk misi ini, gunakan '+req.map(t=>t==='repeat'?'kotak Ulang':t==='function'?'Jurus Irama':'mesin Jika merah').join(' dan ')+'.');if(E.validate(m,state.program))win();else showThinking(true,m.id>=1000?lessonClue():'');}
// Original, offline sound effects. Short envelopes avoid sharp clicks and loud stacking.
const GameSFX=(()=>{
 const voices=new Set();let last=-Infinity;
 const sounds={tap:[[520,720,0,.07]],drop:[[380,650,0,.12],[780,950,.06,.10]],remove:[[660,330,0,.12]],flip:[[440,880,0,.09]],step:[[180,280,0,.07]],star:[[880,880,0,.12],[1320,1320,.09,.18]],magic:[[523,660,0,.13],[784,988,.10,.16],[1047,1397,.22,.20]],retry:[[392,350,0,.18],[440,440,.17,.22]],hint:[[660,784,0,.13],[988,988,.12,.19]],success:[[523,523,0,.16],[659,659,.13,.16],[784,784,.26,.18],[1047,1047,.42,.32]]};
 function stop(){for(const v of voices){try{v.osc.stop();}catch{}v.osc.disconnect();v.gain.disconnect();}voices.clear();}
 function play(name='tap'){
  if(!sound)return;
  try{
   const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
   audioCtx??=new Audio();if(audioCtx.state==='suspended')audioCtx.resume()?.catch(()=>{});
   const now=audioCtx.currentTime;
   if(now-last<.035&&['tap','drop','flip','step'].includes(name))return;
   last=now;if(['success','retry'].includes(name)||voices.size>10)stop();
   for(const [from,to,delay,duration] of sounds[name]||sounds.tap){
    const osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),voice={osc,gain},at=now+delay;
    osc.type=name==='step'?'triangle':'sine';osc.frequency.setValueAtTime(from,at);osc.frequency.exponentialRampToValueAtTime(to,at+duration);
    gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(name==='success'?.045:.028,at+.012);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);
    osc.connect(gain);gain.connect(audioCtx.destination);voices.add(voice);
    osc.onended=()=>{voices.delete(voice);osc.disconnect();gain.disconnect();};osc.start(at);osc.stop(at+duration+.02);
   }
  }catch{} // Audio must never block a game on unsupported browsers.
 }
 return {play,stop};
})();
function playNote(v){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=[330,220,660,440][+v]||330;g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.25);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.3);}catch{}}
async function listenMusic(){if(state.busy)return;sound=true;updateSound();state.busy=true;const token=epoch;for(let i=0;i<m.target.length;i++){if(token!==epoch)return;state.playing=i;playNote(m.target[i]);renderGame();await new Promise(r=>setTimeout(r,420));}if(token!==epoch)return;state.playing=-1;state.busy=false;renderGame();setStatus('Sekarang giliranmu menyusun irama yang sama.');}
