function parents(){stop();if(m)renderGame();showDialog(`<span class="eyebrow">PETUALANGAN DENGAN PENDAMPING</span><h2>Banyak misi, tanpa buru-buru.</h2><p><b>1.045 misi: 10 permainan awal × 20 tema × 5 tingkat, ditambah 45 misi Sebab Akibat, Urutan Cerita, dan Detektif Kode.</b> Isi dibangkitkan secara deterministik: misi yang sama tetap sama setiap dibuka. Variasinya mencakup pilihan, pola, petunjuk, aturan, dan susunan; bukan 1.000 kurikulum yang sepenuhnya berbeda.</p><p>Untuk anak usia 6 tahun, mulai dari tingkat 1. Tingkat 4–5 merupakan tantangan lanjutan dengan pendamping, bukan target yang harus segera dikuasai. Satu misi bisa menjadi satu pertemuan singkat, diulang, atau dikembangkan tanpa layar.</p><div class="parent-rhythm"><span>👐 5 menit<br><b>Gerak & benda nyata</b></span><span>🧩 10 menit<br><b>Main & mencoba</b></span><span>💬 5 menit<br><b>Cerita caranya</b></span></div><p>Sesuaikan durasi dengan anak. Rayakan caranya mencoba dan menjelaskan. Jika masih bingung, mainkan contoh dengan benda nyata sebelum kembali ke layar.</p>${voiceSettings()}<h3>Jenjang tantangan</h3><div class="curriculum">${E.levels.map((l,i)=>`<details><summary>${l.icon} Tingkat ${i+1}: ${l.name} · misi ${i*200+1}–${(i+1)*200}</summary><p>${l.description}</p><p>${['Pasangan 3 pasang, pengelompokan warna, pola AB, puzzle 2×2, dan logika 3×3 dengan sedikit kotak kosong.','Pasangan 4 pasang, pengelompokan gambar, pola ABC, lebih banyak kotak kosong, dan pengulangan irama.','Pasangan 5 pasang, gabungan gambar–warna, puzzle 3×3, logika 4×4, serta mesin pengulangan.','Pasangan 6 pasang, aturan DAN, petunjuk negatif, kondisi mesin, fungsi irama, dan dua tas bekal.','Pasangan 8 pasang, aturan ATAU + DAN, pola gabungan, puzzle 4×4, kondisi dalam pengulangan, dan batas jumlah bekal.'][i]}</p></details>`).join('')}</div><h3>13 cara melatih logika</h3><div class="curriculum">${E.types.map(t=>`<details><summary>${t.icon} ${t.name} · ${t.skill}</summary><p>${t.goal}</p><p>Tanpa layar: ${t.off}</p><p>Refleksi: ${t.reflect}</p></details>`).join('')}</div><p><b>Progres:</b> ${progress.done.length}/1.045. Hanya tersimpan di browser ini. Ekspor cadangan dan impor untuk menggabungkan progres di perangkat lain. Versi baru memakai progres terpisah dari 40 misi versi awal.</p><div class="parent-actions"><button class="secondary" data-action="export">↓ Cadangkan progres</button><label class="secondary file-label">↑ Impor progres<input id="importFile" type="file" accept="application/json,.json"></label><button class="secondary" data-action="print">Cetak panduan</button><button class="secondary" data-action="guideDownload">↓ Panduan semua misi</button></div><p id="importStatus" role="status" class="mini-help"></p><p class="mini-help">Suara memerlukan dukungan browser. Game tetap dapat digunakan tanpa suara atau internet. Tanda ● ■ ▲ ◆ membantu membedakan warna.</p><a class="text-link" href="classic/index.html">Buka 40 misi arah versi awal →</a>`);bindVoiceSettings();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('Berkas terlalu besar');const raw=JSON.parse(await f.text());if(raw.version!==3)throw Error('Pilih berkas cadangan Kode Kecil versi 3');const p=cleanProgress(raw);progress.done=[...new Set([...progress.done,...p.done])];save();$('#importStatus').textContent=`${progress.done.length} misi selesai setelah progres digabung. ${storageOK?'Tersimpan.':'Penyimpanan browser tidak tersedia.'}`;}catch(err){$('#importStatus').textContent='Belum bisa diimpor: '+err.message;}};}
function guideDownload(){const lines=['# Kode Kecil — Panduan 1.045 Misi','','13 jenis permainan, 1.045 misi. Setiap permainan memiliki jalur level sendiri. Misi yang sama konsisten setiap dibuka.','','Untuk usia 6 tahun, mulai dari tingkat 1 dengan pendamping. Tingkat lanjut menambah tantangan, bukan kewajiban usia. Usulan sesi: 5 menit tanpa layar, 10 menit bermain, 5 menit cerita. Boleh lebih singkat, diulang, atau dijeda.','','## Jenis permainan',...E.types.flatMap(t=>['',`### ${t.name}`,t.goal,`Tanpa layar: ${t.off}`,`Refleksi: ${t.reflect}`]),'','## Daftar pertemuan'];for(let id=0;id<TOTAL_MISSIONS;id++){const x=E.make(id);lines.push(`${id+1}. Tingkat ${x.level+1} — ${E.themes[x.theme].name} — ${x.title}: ${x.skill}. ${E.describe(x)}`);}download('panduan-1000-misi-kode-kecil.md',lines.join('\n'),'text/markdown');}
