async function action(a,v){if(a==='voicePreview'){speak('Hai, aku Bimo! Yuk, kita main bersama. Hmm, menurutmu, kartu ini cocok di mana? Pelan-pelan saja. Kamu pasti bisa mencoba!',true);return;}if(a==='voiceStop'){BimoVoice.stop();return;}if(a==='close'){BimoVoice.stop();dialog.close();return;}if(a==='closeHome'){dialog.close();home();return;}if(a==='closePath'){dialog.close();return journey(v);}if(a==='journey')return journey(v);if(a==='next'){dialog.close();if(unlocked(+v))openMission(+v);return;}if(a==='home')return home();if(a==='chapter')return chapter(+v);if(a==='open'){if(unlocked(+v))return openMission(+v);return;}if(a==='resume')return openMission(next());if(a==='filter')return journey(v);if(a==='alltypes'){filter=null;home();return;}if(a==='level'){level=+v;home();$('.map-section').scrollIntoView();return;}if(a==='export')return download('kode-kecil-progres.json',JSON.stringify({version:3,...progress},null,2),'application/json');if(a==='print'){dialog.querySelectorAll('details').forEach(d=>d.open=true);window.print();return;}if(a==='guideDownload')return guideDownload();if(!m||!state)return;if(a==='reset'){stop();state=initState();GameSFX.play('remove');renderGame();setStatus(initialMessage());return;}if(a==='hint')return hint();if(a==='listen'||a==='clues'){if(!('speechSynthesis'in window))return setStatus('Browser ini belum menyediakan pembacaan suara. Pendamping bisa membacakan petunjuk.');speak(a==='clues'?m.rules.map(ruleText).join(' '):'Yuk, kita coba! '+missionBrief()+' Pelan-pelan saja, ya.',true);return;}if(state.busy)return;if(playfulAction(a,v))return;if(a==='check')return check();if(a==='listenMusic')return listenMusic();if(a==='memory')return memory(+v);if(a==='returnSort'){if(m.type!=='sort'||state.selection!==+v)return setStatus('Pilih kartu di rumah, lalu tempat asalnya yang kosong.');return applyDrop('sort',v,{dataset:{dropKind:'sort-slot',value:v}});}
const moveFrom=GameMotion.rect(document.querySelector(a==='bin'?`[data-action="select"][data-value="${state.selection}"]`:a==='bag'?`[data-action="provision"][data-value="${state.selection}"]`:a==='pattern'?`[data-action="pattern"][data-value="${v}"]`:a==='matrix'?`[data-action="matrix"][data-value="${v}"]`:a==='add'?`[data-action="add"][data-value="${v}"]`:'#no-motion-source'));const moveSlot=state.selection;
if(a==='cause'){const [q,c]=v.split(':').map(Number);state.answer[q]=c;}else if(a==='story'){if(state.selection===null)state.selection=+v;else{const i=state.selection;[state.answer[i],state.answer[+v]]=[state.answer[+v],state.answer[i]];state.selection=null;}}else if(a==='select'){state.selection=+v;}else if(a==='bin'){if(state.selection===null)return setStatus('Pilih satu kartu dulu, lalu rumahnya.');state.answer[state.selection]=+v;state.selection=null;setStatus('Kartu masuk rumah. Boleh dipindahkan lagi kalau berubah pikiran.');}else if(a==='pattern'){if(state.selection===null)return setStatus('Pilih gerbong yang kosong dulu.');state.answer[state.selection]=clone(m.choices[+v]);const empty=state.answer.findIndex(c=>!c);if(empty>=0)state.selection=empty;}else if(a==='tile'){if(state.selection===null)state.selection=+v;else{const i=state.selection;[state.answer[i],state.answer[+v]]=[state.answer[+v],state.answer[i]];state.selection=null;}}else if(a==='matrix'){if(state.selection===null||m.clues[state.selection]>=0)return setStatus('Pilih kotak tanpa gembok dulu.');state.answer[state.selection]=+v;}else if(a==='fixed')return setStatus('Kotak bergembok adalah petunjuk. Pilih kotak yang bisa kamu isi.');else if(a==='suspect'){state.answer=+v;state.crossed=(state.crossed||[]).filter(i=>i!==+v);}else if(a==='provision'){if(state.answer[+v]>=0){state.answer[+v]=-1;state.selection=null;}else state.selection=+v;}else if(a==='bag'){if(state.selection===null)return setStatus('Pilih satu bekal dulu, lalu pilih tas.');state.answer[state.selection]=+v;state.selection=null;}else if(a==='add'){if(state.program.length>=30)return setStatus('Rencananya sudah panjang. Hapus kartu atau gunakan Ulang.');state.program.push({type:v});state.active=-1;}else if(a==='remove'){state.program.splice(+v,1);state.active=-1;}else if(a==='undo')state.program.pop();else if(a==='clearProgram'){state.program=[];state.active=-1;}else if(a==='repeat'){if(!state.program.length)return setStatus('Susun pola pendek dulu, baru ketuk Ulang.');if(E.has(state.program,'repeat'))return setStatus('Untuk misi ini cukup satu lapis Ulang. Susun ulang jika ingin mengganti jumlahnya.');state.program=[{type:'repeat',count:+v,body:clone(state.program)}];}else if(a==='saveFn'){if(!state.program.length)return setStatus('Susun irama dulu, lalu simpan sebagai Jurus.');if(E.has(state.program,'function'))return setStatus('Buat jurus dari bunyi dan pengulangan, tanpa memanggil dirinya sendiri.');state.fn=clone(state.program);state.program=[];}else if(a==='callFn'){if(!state.fn.length)return setStatus('Simpan rangkaian bunyi menjadi Jurus dulu.');if(state.program.length>=30)return setStatus('Hapus beberapa kartu dulu.');state.program.push({type:'function',body:clone(state.fn)});}if(moveFrom){const keys={bin:'placed-sort-'+moveSlot,bag:'placed-packing-'+moveSlot,pattern:'pattern-'+moveSlot,matrix:'matrix-'+moveSlot};if(keys[a])GameMotion.seed(keys[a],moveFrom);else if(a==='add')GameMotion.seed(GameMotion.key(state.program[state.program.length-1]),moveFrom);}state.dotCount=0;renderGame();const motionTargets={bin:'.bin',bag:'.bag',suspect:'.suspect.selected',saveFn:'.function-box'};if(motionTargets[a]||['cause','story','tile','pattern','matrix','add','repeat','callFn','remove','undo','clearProgram','provision'].includes(a))setStatus('Sudah diubah! Menurutmu, sekarang sudah cocok? 🌱');if(motionTargets[a])animatePlay(motionTargets[a]);if(a==='cause')return check();}
dialog.addEventListener('close',()=>BimoVoice.stop());
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){const a=b.dataset.action;if(!state?.busy&&!['check','cause','memory','hint','listen','listenMusic','audition','clues','reset'].includes(a))GameSFX.play(['remove','undo','clearProgram'].includes(a)?'remove':['add','bin','bag','matrix','pattern','repeat','callFn'].includes(a)?'drop':'tap');action(a,b.dataset.value);}});$('#brand').onclick=e=>{e.preventDefault();home();};$('#mapBtn').onclick=home;$('#parentsBtn').onclick=parents;$('#soundBtn').onclick=()=>{sound=!sound;updateSound();if(sound){GameSFX.play('star');speak('Hai, aku Bimo! Siap main bersama? Yuk, kita coba!');}else{GameSFX.stop();if(audioCtx)audioCtx.suspend()?.catch(()=>{});BimoVoice.stop();}};home();
